#include <cmath>
#include <algorithm>

class Solution {
    bool isBetween(int a, int b, int c) {
        return std::min(a, c) < b && b < std::max(a, c);
    }
public:
    int minQueenMoves(int qr, int qc, int tr, int tc, int br, int bc) {
        if (qr == tr && qc == tc) return 0;

        if (qr == tr) {
            if (br == qr && isBetween(qc, bc, tc)) return 2;
            return 1;
        }
        if (qc == tc) {
            if (bc == qc && isBetween(qr, br, tr)) return 2;
            return 1;
        }
        if (std::abs(qr - tr) == std::abs(qc - tc)) {
            if (std::abs(qr - br) == std::abs(qc - bc) && std::abs(br - tr) == std::abs(bc - tc)) {
                if (isBetween(qr, br, tr) && isBetween(qc, bc, tc)) return 2;
            }
            return 1;
        }
        return 2;
    }
};

class Solution {
    private boolean isBetween(int a, int b, int c) {
        return Math.min(a, c) < b && b < Math.max(a, c);
    }

    public int minQueenMoves(int qr, int qc, int tr, int tc, int br, int bc) {
        if (qr == tr && qc == tc) return 0;

        if (qr == tr) {
            if (br == qr && isBetween(qc, bc, tc)) return 2;
            return 1;
        }
        if (qc == tc) {
            if (bc == qc && isBetween(qr, br, tr)) return 2;
            return 1;
        }
        if (Math.abs(qr - tr) == Math.abs(qc - tc)) {
            if (Math.abs(qr - br) == Math.abs(qc - bc) && Math.abs(br - tr) == Math.abs(bc - tc)) {
                if (isBetween(qr, br, tr) && isBetween(qc, bc, tc)) return 2;
            }
            return 1;
        }
        return 2;
    }
}

